import json, os, sys
import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import t60_map as tm
from calibrate_same import measure

ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
LIBRARY = os.path.abspath(os.path.join(ROOT, '..', 'refer', 'sample', 'The Gentleman'))
MODES = os.path.join(ROOT, 'target', 'wav', 'gentleman-model', 'modes.json')
OUT = os.path.join(ROOT, 'i_am_string', 'src', 'piano_calibration.rs')

HEAD = '''//! The piano, measured against The Gentleman at the same frequencies.
//!
//! Generated by tools/table_from_sample.py. Rows are
//! (frequency, gain, prompt T60, tail T60); the mode bank is built from these
//! rows when the note is calibrated.

/// One measured partial.
#[derive(Clone, Copy, Debug)]
pub struct Mode {
	/// Where the partial sits, in hertz.
	pub frequency: f32,
	/// The partial's level, relative to the note.
	pub gain: f32,
	/// T60 of the prompt decay, in seconds.
	pub prompt: f32,
	/// T60 of the tail, in seconds.
	pub tail: f32,
}

/// The rows for one note, empty when the note was not measured.
pub fn modes(note: u8) -> &'static [Mode] {
	match note {
'''

def main():
    library = json.load(open(MODES))
    rows_by_note = {}
    for entry in library:
        rate, target = tm.load(os.path.join(LIBRARY, entry['file']))
        f0 = 440.0 * 2.0 ** ((entry['note'] - 69) / 12.0)
        rows = []
        for mode in entry['modes']:
            got = measure(target, rate, mode['f'], f0)
            if got is None:
                continue
            rows.append((mode['f'], got['amp'], got['prompt'], got['tail']))
        if len(rows) < 3:
            continue
        peak = max(row[1] for row in rows)
        rows_by_note[entry['note']] = [(row[0], row[1] / peak, row[2], row[3])
                                       for row in rows]
    # Fill the rest of the keyboard by transposing the nearest measured note:

    # the partials scale with the fundamental, and the shape of the note is

    # carried along. A table with holes in it is worse than a coarse one.

    measured = sorted(rows_by_note)

    full = {}

    for note in range(21, 109):

        source = min(measured, key=lambda other: abs(other - note))

        ratio = 2.0 ** ((note - source) / 12.0)

        full[note] = [(row[0] * ratio, row[1], row[2], row[3])

                      for row in rows_by_note[source]]

    rows_by_note = full

    body = []

    for note in sorted(rows_by_note):
        cells = ', '.join('Mode { frequency: %.1f, gain: %.3f, prompt: %.3f, tail: %.3f }' % row
                          for row in rows_by_note[note])
        body.append('\t\t%d => &[%s],' % (note, cells))
    text = HEAD + '\n'.join(body) + '\n\t\t_ => &[],\n\t}\n}\n'
    open(OUT, 'w').write(text)
    print('wrote', OUT)

main()